function knapsack(weights, values, cap) {
  const n = weights.length, dp = Array.from({ length: n + 1 }, () => Array(cap + 1).fill(0)) //@init
  for (let i = 1; i <= n; i++) {
    const w = weights[i - 1], v = values[i - 1] //@item
    for (let c = 0; c <= cap; c++) {
      dp[i][c] = dp[i - 1][c] //@skip
      if (w <= c) dp[i][c] = Math.max(dp[i][c], dp[i - 1][c - w] + v) //@take
    }
  }
  return dp[n][cap] //@done
}

