    best = [0] * (cap + 1)  # best[c] = best value within capacity c
    for w, v in zip(weights, values):
        for c in range(cap, w - 1, -1):  # downwards: each item at most once
            best[c] = max(best[c], best[c - w] + v)  # skip or take
    return best[cap]

