function solve(weights, values, cap) {
  const best = Array(cap + 1).fill(0) // best[c] = best value within capacity c
  weights.forEach((w, i) => {
    for (let c = cap; c >= w; c--) { // downwards: each item at most once
      best[c] = Math.max(best[c], best[c - w] + values[i]) // skip or take
    }
  })
  return best[cap]
}

