function canSplitEqual(nums) {
  const total = nums.reduce((a, b) => a + b, 0)
  if (total % 2) return false
  const half = total / 2
  const can = Array(half + 1).fill(false)
  can[0] = true
  for (const x of nums) {
    for (let s = x; s <= half; s++) can[s] = can[s] || can[s - x]
  }
  return can[half]
}

